import { historicDistrictAt } from './districts.js';
import { GEO } from './nyc-geodata.js';

// Ann Arbor, Michigan at true 1:1 scale, from the real geography in js/nyc-geodata.js (generated by
// Assets/Tools/build-annarbor.py from OpenStreetMap and the City of Ann Arbor's open data).
//
// World frame: 1 unit = 1 m, x = east, z = south (north = -z), origin at the centreline intersection of Main St &
// Liberty St downtown, true north up. The detailed city runs from about Stadium Blvd's west end to Gallup Park, and
// from the North Campus hills down to I-94; beyond it the countryside rolls on to the fogged horizon (outskirts.js).
// The old Manhattan names of a few exports stay (MANHATTAN_COASTLINE is the detailed area's edge) so every part of
// the game keeps reading the city the same way; the grid-only parts (numbered streets, avenues, bridges) are empty.

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};
const CUT_Z = GEO.frame.cutZ;
const FAR = 1e6; // somewhere nothing is

// No numbered street grid here: a street "number" falls back to a spacing from downtown, so older code that asks
// still gets a number rather than an error
const streetZ = (n) => (42 - n) * 80;
const ALL_AVENUES = [];
const avenueX = () => FAR;
const AVENUES = [];
const STREETS = [];
const ALL_STREETS = [];

// No Central Park: its bounds are far away, so every "inside the park" test is false
const CENTRAL_PARK_BOUNDS = { minX: FAR, maxX: FAR + 1, minZ: FAR, maxZ: FAR + 1 };

// The detailed area's edge (a rectangle around the city): the "shore" tests find land everywhere inside it
const MANHATTAN_COASTLINE = toPts(GEO.manhattan);
const ISLAND_BOUNDS = (() => {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const p of MANHATTAN_COASTLINE) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
  }
  return { minX, maxX, minZ, maxZ, sidewalkHeight: 0.22, waterLevel: -2.2 };
})();
function getIslandBoundsAtZ() {
  return { westX: ISLAND_BOUNDS.minX, eastX: ISLAND_BOUNDS.maxX };
}
const BROADWAY_LINE = [];
const getBroadwayX = () => FAR;

// Water: the Huron River, its ponds (Argo, Barton, Geddes) and the lakes, as polygons with holes [[outer, ...holes]]
const WATER_POLYGONS = GEO.water.map((rings) => rings.map(toPts));
// Surface parking lots (drawn as asphalt on the lawns)
const PARKING_LOTS = GEO.parking.map((rings) => rings.map(toPts));

// No harbour, islands, boroughs, piers or bridges in Ann Arbor
const WATERFRONT_PIERS = [];
const ROOSEVELT_ISLAND_POLYGON = [];
const GOVERNORS_ISLAND_POLYGON = [];
const RANDALLS_ISLAND_POLYGON = [];
const LIBERTY_ISLAND_POLYGON = [];
const ELLIS_ISLAND_POLYGON = [];
const MILL_ROCK_POLYGON = [];
const LIBERTY_STATUE_POS = { x: FAR, z: FAR };
const NJ_SHORELINE_POLYGON = [];
const BROOKLYN_POLYGONS = [];
const QUEENS_POLYGONS = [];
const BRONX_POLYGONS = [];
const STATEN_ISLAND_POLYGON = [];
const LONG_ISLAND_POLYGONS = [];
const BRONX_POLYGON = [];
const UPPER_MANHATTAN_POLYGON = [];
const WESTCHESTER_POLYGON = [];
const NASSAU_POLYGON = [];
const EAST_RIVER_BRIDGES = [];
const OUTER_BRIDGES = [];

// Named roads (the real centreline of each OpenStreetMap way) — maps, labels & lookups
const ROADS = GEO.roads.map(([name, w, dir, lanes, hw, flat]) => ({ name, raw: name, w, dir, lanes, highway: !!hw, pts: toPts(flat) }));

// Nearest-road index (labels, sidewalk tests): uniform grid of road segments
const ROAD_CELL = 64;
const ROAD_GRID = new Map();
for (const r of ROADS) {
  for (let i = 0; i + 1 < r.pts.length; i++) {
    const a = r.pts[i];
    const b = r.pts[i + 1];
    const seg = { r, ax: a.x, az: a.z, bx: b.x, bz: b.z };
    const ix0 = Math.floor(Math.min(a.x, b.x) / ROAD_CELL), ix1 = Math.floor(Math.max(a.x, b.x) / ROAD_CELL);
    const iz0 = Math.floor(Math.min(a.z, b.z) / ROAD_CELL), iz1 = Math.floor(Math.max(a.z, b.z) / ROAD_CELL);
    for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
      const k = ix * 100000 + iz;
      if (!ROAD_GRID.has(k)) ROAD_GRID.set(k, []);
      ROAD_GRID.get(k).push(seg);
    }
  }
}
/** Nearest roads to (x, z) within `radius`: [{ road, dist }] sorted by distance (one entry per road name) */
function nearestRoads(x, z, radius = 60) {
  const best = new Map();
  const ix0 = Math.floor((x - radius) / ROAD_CELL), ix1 = Math.floor((x + radius) / ROAD_CELL);
  const iz0 = Math.floor((z - radius) / ROAD_CELL), iz1 = Math.floor((z + radius) / ROAD_CELL);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = ROAD_GRID.get(ix * 100000 + iz);
    if (!list) continue;
    for (const s of list) {
      const dx = s.bx - s.ax, dz = s.bz - s.az;
      const L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
      const d = Math.hypot(s.ax + t * dx - x, s.az + t * dz - z);
      if (d > radius) continue;
      const prev = best.get(s.r.name);
      if (!prev || d < prev.dist) best.set(s.r.name, { road: s.r, dist: d, horizontal: Math.abs(dx) > Math.abs(dz) });
    }
  }
  return [...best.values()].sort((a, b) => a.dist - b.dist);
}

// ---------------------------------------------------------------------------------------------------------------------
// Blocks: every real curb island (raised sidewalk slab) with its lot rectangles inside the property line
//   poly: curb outline [{x, z}], rects: [[x0, x1, z0, z1], ...] building lots (axis-aligned; one for a grid block),
//   park: share covered by parkland (NYC Parks), parkName, rect: the island is an axis-aligned rectangle,
//   lawn: a residential or campus block, green inside its sidewalk ring rather than paved to the lot line,
//   frames: irregular islands' lots laid out along the streets they front, [[θ, px, pz, rects], ...] (rects in a
//   frame turned by θ about (px, pz): world = p + R_y(θ)·(local − p)), or null
// ---------------------------------------------------------------------------------------------------------------------
const BLOCKS = GEO.blocks.map(([flat, rects, park, parkName, isRect, frames, lawn], id) => {
  const poly = toPts(flat);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, a = 0, cx = 0, cz = 0;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const p = poly[i], q = poly[j];
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    const c = q.x * p.z - p.x * q.z;
    a += c; cx += (q.x + p.x) * c; cz += (q.z + p.z) * c;
  }
  a *= 0.5;
  const area = Math.abs(a);
  return {
    id, poly, rects, frames: frames || null, park, parkName, rect: !!isRect, area, lawn: !!lawn,
    minX, maxX, minZ, maxZ,
    cx: a ? cx / (6 * a) : (minX + maxX) / 2,
    cz: a ? cz / (6 * a) : (minZ + maxZ) / 2,
    median: /Malls?$/.test(parkName) || Math.min(maxX - minX, maxZ - minZ) < 9
  };
});
// Spatial index of the blocks (64 m cells)
const BLOCK_CELL = 64;
const BLOCK_GRID = new Map();
for (const b of BLOCKS) {
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!BLOCK_GRID.has(k)) BLOCK_GRID.set(k, []);
      BLOCK_GRID.get(k).push(b);
    }
  }
}
function pointInPoly(poly, x, z) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a.z > z) !== (b.z > z) && x < ((b.x - a.x) * (z - a.z)) / (b.z - a.z) + a.x) inside = !inside;
  }
  return inside;
}
/** The block (curb island) under (x, z), or null on the roadway / in the water */
function blockAt(x, z) {
  const list = BLOCK_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (b.rect || pointInPoly(b.poly, x, z)) return b;
  }
  return null;
}

// ---------------------------------------------------------------------------------------------------------------------
// Neighbourhoods (for building styles, labels & the maps)
// ---------------------------------------------------------------------------------------------------------------------
const AREAS = [
  // [id, label, minX, maxX, minZ, maxZ], first match wins
  ['downtown', 'Downtown', -260, 420, -420, 420],
  ['kerrytown', 'Kerrytown', -60, 520, -820, -420],
  ['state_street', 'State Street', 420, 640, -150, 520],
  ['central_campus', 'Central Campus', 640, 1350, -260, 700],
  ['medical_campus', 'Medical Campus', 900, 1900, -1150, -260],
  ['north_campus', 'North Campus', 1700, 4600, -3200, -1300],
  ['athletic_campus', 'South Campus', -400, 900, 700, 2100],
  ['burns_park', 'Burns Park', 1200, 2400, 700, 2100],
  ['old_west_side', 'Old West Side', -1400, -260, -420, 1000],
  ['water_hill', 'Water Hill', -1400, -60, -1300, -420],
  ['lower_town', 'Lower Town', 300, 1700, -1700, -820],
  ['geddes', 'Geddes & the Arb', 1350, 3600, -260, 700]
];
function districtAt(x, z) {
  for (const [id, , x0, x1, z0, z1] of AREAS) if (x >= x0 && x <= x1 && z >= z0 && z <= z1) return id;
  return 'neighborhood';
}
const districtLabel = (id) => (AREAS.find((a) => a[0] === id) || [0, 'Ann Arbor'])[1];
for (const b of BLOCKS) b.district = districtAt(b.cx, b.cz);

// ---------------------------------------------------------------------------------------------------------------------
// Landmarks (real footprints from OpenStreetMap: centre, width x depth, height)
// ---------------------------------------------------------------------------------------------------------------------
const LANDMARK_SITES = GEO.landmarks;
const site = (name, fallback) => LANDMARK_SITES[name] || fallback;
const NYC_LANDMARKS = [
  ['stadium', 'Michigan Stadium (The Big House)', 'The Big House', 'Michigan Stadium'],
  ['burton', 'Burton Memorial Tower', 'Burton Tower', 'Burton Memorial Tower'],
  ['diag', 'The Diag & Hatcher Library', 'The Diag', 'The Diag'],
  ['hill', 'Hill Auditorium', 'Hill Auditorium', 'Hill Auditorium'],
  ['union', 'Michigan Union', 'Michigan Union', 'Michigan Union'],
  ['league', 'Michigan League', 'Michigan League', 'Michigan League'],
  ['theater', 'Michigan Theater', 'Michigan Theater', 'Michigan Theater'],
  ['umma', 'Museum of Art', 'UMMA', 'University of Michigan Museum of Art'],
  ['rackham', 'Rackham Building', 'Rackham', 'Rackham Building'],
  ['crisler', 'Crisler Center', 'Crisler Center', 'Crisler Center'],
  ['yost', 'Yost Ice Arena', 'Yost Arena', 'Yost Ice Arena'],
  ['kerrytown', 'Kerrytown Market & Shops', 'Kerrytown', 'Kerrytown Market & Shops'],
  ['market', 'Ann Arbor Farmers Market', 'Farmers Market', 'Ann Arbor Farmers Market'],
  ['library', 'Ann Arbor District Library', 'Library', 'Ann Arbor District Library'],
  ['towerplaza', 'Tower Plaza', 'Tower Plaza', 'Tower Plaza'],
  ['arb', 'Nichols Arboretum', 'The Arb', 'Nichols Arboretum'],
  ['gallup', 'Gallup Park', 'Gallup Park', 'Gallup Park'],
  ['westpark', 'West Park', 'West Park', 'West Park'],
  ['fuller', 'Fuller Park', 'Fuller Park', 'Fuller Park'],
  ['burnspark', 'Burns Park', 'Burns Park', 'Burns Park']
].flatMap(([id, name, short, osm]) => {
  const s = site(osm, null);
  return s ? [{ id, name, short, x: s.x, z: s.z, district: districtLabel(districtAt(s.x, s.z)) }] : [];
});
// The Amtrak station on Depot St (by its real place: OpenStreetMap's name for it is just "Ann Arbor")
NYC_LANDMARKS.push({ id: 'amtrak', name: 'Ann Arbor Amtrak Station', short: 'Amtrak', x: 432, z: -905, district: 'Lower Town' });

// Street-level arrivals shared by every travel mode: the nearest point of a named street to each place, facing it.
// Heading 0 faces south (+z), PI north.
function arrival(x, z, fallback) {
  const near = nearestRoads(x, z, 260).filter((r) => !r.road.highway);
  if (!near.length) return { x: fallback.x, z: fallback.z, heading: 0 };
  const { road } = near[0];
  let best = null;
  for (let i = 0; i + 1 < road.pts.length; i++) {
    const a = road.pts[i], b = road.pts[i + 1];
    const dx = b.x - a.x, dz = b.z - a.z, L2 = dx * dx + dz * dz || 1e-9;
    const t = Math.max(0, Math.min(1, ((x - a.x) * dx + (z - a.z) * dz) / L2));
    const px = a.x + t * dx, pz = a.z + t * dz, d = Math.hypot(px - x, pz - z);
    if (!best || d < best.d) best = { d, px, pz, dx, dz };
  }
  // stand on the right-hand lane, looking toward the place
  const L = Math.hypot(best.dx, best.dz) || 1;
  const side = Math.sign((x - best.px) * (-best.dz / L) + (z - best.pz) * (best.dx / L)) || 1;
  const px = best.px + (-best.dz / L) * side * Math.min(3.5, road.w * 0.25);
  const pz = best.pz + (best.dx / L) * side * Math.min(3.5, road.w * 0.25);
  return { x: px, z: pz, heading: Math.atan2(x - px, z - pz) };
}
const lm = (id) => NYC_LANDMARKS.find((l) => l.id === id) || { x: 0, z: 0 };
const TELEPORT_LOCATIONS = {
  mainst: { x: -19.2, z: 112, heading: Math.PI }, // Main St between William and Liberty, looking north up Main
  diag: arrival(lm('diag').x, lm('diag').z, lm('diag')),
  stadium: arrival(lm('stadium').x, lm('stadium').z, lm('stadium')),
  burton: arrival(lm('burton').x, lm('burton').z, lm('burton')),
  theater: arrival(lm('theater').x, lm('theater').z, lm('theater')),
  kerrytown: arrival(lm('kerrytown').x, lm('kerrytown').z, lm('kerrytown')),
  arb: arrival(lm('arb').x, lm('arb').z, lm('arb')),
  gallup: arrival(lm('gallup').x, lm('gallup').z, lm('gallup')),
  hill: arrival(lm('hill').x, lm('hill').z, lm('hill')),
  union: arrival(lm('union').x, lm('union').z, lm('union')),
  umma: arrival(lm('umma').x, lm('umma').z, lm('umma')),
  library: arrival(lm('library').x, lm('library').z, lm('library')),
  crisler: arrival(lm('crisler').x, lm('crisler').z, lm('crisler')),
  amtrak: arrival(lm('amtrak').x, lm('amtrak').z, lm('amtrak'))
};

// The city's building names (Bldg_Name, GEO.places): each named building's centre and half its size, in 100 m cells
const PLACE_CELL = 100;
const placeCells = new Map();
{
  const { names = [], list = [] } = GEO.places || {};
  for (let i = 0; i < list.length; i += 4) {
    const key = Math.floor(list[i] / PLACE_CELL) + ',' + Math.floor(list[i + 1] / PLACE_CELL);
    if (!placeCells.has(key)) placeCells.set(key, []);
    placeCells.get(key).push({ x: list[i], z: list[i + 1], r: list[i + 2], name: names[list[i + 3]] });
  }
}
// The named building you're beside (within 14 m of its edge, roughly), or null
function buildingNameAt(x, z) {
  const cx = Math.floor(x / PLACE_CELL), cz = Math.floor(z / PLACE_CELL);
  let best = null, bestD = Infinity;
  for (let i = -1; i <= 1; i++) {
    for (let j = -1; j <= 1; j++) {
      for (const p of placeCells.get(cx + i + ',' + (cz + j)) || []) {
        const d = Math.hypot(x - p.x, z - p.z) - p.r;
        if (d < 14 && d < bestD) { best = p; bestD = d; }
      }
    }
  }
  return best ? best.name : null;
}

/**
 * The street, crossing or place at any world (x, z): a landmark close by, else the named building you're beside with
 * its street, else the nearest two named roads
 */
function getLocationLabel(x, z) {
  for (const l of NYC_LANDMARKS) {
    if (Math.hypot(x - l.x, z - l.z) < 90) {
      const near = nearestRoads(x, z, 120);
      return `${l.name}${near.length ? ` · ${near[0].road.name}` : ''}`;
    }
  }
  const building = buildingNameAt(x, z);
  if (building) {
    const near = nearestRoads(x, z, 120);
    return `${building}${near.length ? ` · ${near[0].road.name}` : ''}`;
  }
  const b = blockAt(x, z);
  if (b && b.park > 0.6 && b.parkName) return b.parkName;
  const near = nearestRoads(x, z, 160);
  // Lamp: inside one of the city's historic districts, its name over the street signs
  const historic = historicDistrictAt(x, z);
  const lead = historic ? `${historic} · ` : '';
  if (near.length >= 2) return `${lead}${near[0].road.name} & ${near[1].road.name}`;
  if (near.length) return `${lead}${near[0].road.name}`;
  if (historic) return historic;
  if (x < ISLAND_BOUNDS.minX || x > ISLAND_BOUNDS.maxX || z < ISLAND_BOUNDS.minZ || z > ISLAND_BOUNDS.maxZ) return 'Washtenaw County';
  return districtLabel(districtAt(x, z)) === 'Ann Arbor' ? 'Ann Arbor' : `${districtLabel(districtAt(x, z))}, Ann Arbor`;
}

// Positions authored in the old Manhattan frame have no Ann Arbor equivalent: they're taken as they are
const fromOldFrame = (x, z) => ({ x, z });

/** The old midtown superblocks: none here */
function getBlockBounds() {
  return null;
}

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads (street-details.js) and the traffic (traffic.js), in seconds:
// avenues green until avenueAmber, amber until avenueRed; cross streets green from avenueRed until streetAmber,
// amber until the end of the cycle. Pedestrians cross with the traffic that runs parallel to them, stepping off
// only on the WALK, the first `walk` seconds of its green: long enough before the cross traffic's green for the
// slowest walker to get across the widest avenue.
const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };

// 'green', 'amber' or 'red' for avenue or cross street traffic at a given time
function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

// Do pedestrians walking alongside avenue (or cross street) traffic have the WALK at a given time?
function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

